namespace ghidra.util.database.spatial.hyper;




public interface EuclideanHyperSpace<P, B> where P : HyperPoint where B : HyperBox<P, B> {
	List<Dimension<object, P, B>> getDimensions();

	B getFull();

	bool boxesEqual(B a, B b) {
		foreach (Dimension<object, P, B> dim in getDimensions()) {
			if (!Objects.equals(dim.lower(a), dim.lower(b))) {
				return false;
			}
			if (!Objects.equals(dim.upper(a), dim.upper(b))) {
				return false;
			}
		}
		return true;
	}

	default object[] collectBounds(B box) {
		List<Dimension<object, P, B>> dims = getDimensions();
		object[] result = new object[dims.size() * 2];
		for (int i = 0; i < dims.size(); i++) {
			Dimension<object, P, B> d = dims.get(i);
			result[i * 2] = d.lower(box);
			result[i * 2 + 1] = d.upper(box);
		}
		return result;
	}

	bool boxContains(B box, P point) {
		foreach (Dimension<object, P, B> dim in getDimensions()) {
			if (!dim.contains(box, point)) {
				return false;
			}
		}
		return true;
	}

	double boxArea(B box) {
		double result = 1;
		foreach (Dimension<object, P, B> dim in getDimensions()) {
			result *= 1 + dim.measure(box);
		}
		return result;
	}

	double boxMargin(B box) {
		double result = 0;
		foreach (Dimension<object, P, B> dim in getDimensions()) {
			result += 1 + dim.measure(box);
		}
		return result;
	}

	P boxCenter(B box);

	double measureUnion<T>(Dimension<T, P, B> dim, B a, B b) {
		T unionLower = dim.unionLower(a, b);
		T unionUpper = dim.unionUpper(a, b);
		return dim.distance(unionUpper, unionLower);
	}

	double computeAreaUnionBounds(B a, B b) {
		double result = 1;
		foreach (Dimension<object, P, B> dim in getDimensions()) {
			result *= 1 + measureUnion(dim, a, b);
		}
		return result;
	}

	double measureIntersection<T>(Dimension<T, P, B> dim, B a, B b) {
		T intLower = dim.intersectionLower(a, b);
		T intUpper = dim.intersectionUpper(a, b);
		if (dim.compare(intLower, intUpper) > 0) {
			return 0;
		}
		return dim.distance(intUpper, intLower);
	}

	double computeAreaIntersection(B a, B b) {
		double result = 1;
		foreach (Dimension<object, P, B> dim in getDimensions()) {
			double measure = measureIntersection(dim, a, b);
			if (measure == 0) {
				return 0;
			}
			result *= 1 + measure;
		}
		return result;
	}

	double sqDistance(P a, P b) {
		double result = 0;
		foreach (Dimension<object, P, B> dim in getDimensions()) {
			double dist = dim.pointDistance(a, b);
			result += dist * dist;
		}
		return result;
	}

	B boxUnionBounds(B a, B b);

	B boxIntersection(B b, B shape);

	bool boxEncloses(B outer, B inner) {
		foreach (Dimension<object, P, B> dim in getDimensions()) {
			if (!dim.encloses(outer, inner)) {
				return false;
			}
		}
		return true;
	}
}
